_CORR_DECODED = None

#: Set by `tools/fit_corr_seq.py` only; None in the shipped file, where the
#: `if` below is one Python identity test per layer and bills nothing.
_CORR_HOOK = None


def _corr_decode():
    """Base64 -> Python lists. PURE PYTHON, so it bills nothing and cannot make
    the first MLP of a run cost more than the rest."""
    global _CORR_DECODED
    if _CORR_DECODED is None:
        _CORR_DECODED = {
            k: (list(_array.array("f", _base64.b64decode(blob))), tuple(shape))
            for k, (blob, shape) in _CORR_B64.items()}
    return _CORR_DECODED


def _corr_arrays(dtype):
    """The eight stacked weight arrays, REBUILT EVERY `predict`.

    Not cached on the instance, for the same reason `_constants` is not: an
    order-dependent per-MLP cost is refused by certification, and it would price
    a candidate near a multiplier boundary on the wrong side. Two operations per
    array, sixteen per MLP.
    """
    if not _CORR_ON or not _CORR_B64:
        return None
    return {k: fnp.reshape(fnp.asarray(v, dtype=dtype), shape)
            for k, (v, shape) in _corr_decode().items()}


def _corr_raw(mu_pre, sigma, D3, D4, W, D21, mu_prev, mu_out, dtype):
    """The NINE raw per-neuron channels, `(n, 9)`, in the fitted order.

    THE SINGLE IMPLEMENTATION. `tools/fit_corr_seq.py` calls this exact function
    through a hook to build its training rows, so the features the corrector is
    fitted on cannot drift from the features it is served. Writing them twice --
    once here and once in the trainer -- is how a fit silently becomes
    meaningless, and the feature ORDER is a contract shared with
    `tools/anatomy.py` FEATURES and `tools/fit_corr.py`.
    """
    # `fnp.divide`, NOT `dtype(1.0) / sigma`. With the scalar on the left numpy's
    # own `__truediv__` wins the dispatch and flopscope auto-routes with
    # "np.divide(FlopscopeArray) auto-routed to fnp.divide" -- i.e. the operation
    # was nearly billed by the wrong meter. This file's `dG` block records the
    # same rule for products ("the array goes on the LEFT of every scalar
    # product"). The WSL gate caught it as a new stderr line, which is the check
    # RESULTS.md keeps for exactly this ("a candidate that starts emitting new
    # warnings is telling you something"). `fnp.divide` is the operation the
    # auto-route performed, called directly, so the values are bit-identical.
    inv = fnp.divide(dtype(1.0), sigma)
    inv2 = inv * inv
    if D21 is None:
        # The LAST layer never forms D21 -- skipping it is worth 5 matmuls per
        # lineage and is why `last_layer` pruning exists. Its energy channel is
        # therefore a constant zero, which is exactly how the corrector was
        # FITTED for that layer, not an approximation made at inference.
        d21e = mu_out * dtype(0.0)
    else:
        d21e = (D21 * D21).sum(axis=1) * (inv2 * inv2)
    return fnp.stack([mu_pre, sigma, mu_pre * inv,
                      D3 * (inv2 * inv), D4 * (inv2 * inv2),
                      fnp.sqrt((W * W).sum(axis=0)), d21e,
                      mu_out, mu_out - mu_prev.mean()], axis=1)


def _corr_delta(li, corr, mu_pre, sigma, D3, D4, W, D21, mu_prev, mu_out, n,
                dtype):
    """The fitted mean correction for layer `li`, as an `(n,)` array.

    The target's mean and standard deviation are folded into `W3`/`b3` at export
    time, so there is no de-standardisation step to pay for here.
    """
    # SHAPE-GENERIC OR NOTHING (grader contract rule 6). The weight stack has one
    # page per layer of the depth it was FITTED at, and `li` is the real depth, so
    # a deeper MLP than the table would index off the end -- exactly the bug
    # `_K4_LAM` documents above, where an independent Skeptic found every case at
    # 256x32 raising IndexError. Past the table the corrector is DISABLED, not
    # extrapolated: inventing a correction for a depth we never fitted is the
    # same error one layer further out.
    if li >= corr["W1"].shape[0]:
        return dtype(0.0)
    X = _corr_raw(mu_pre, sigma, D3, D4, W, D21, mu_prev, mu_out, dtype)
    X = fnp.concatenate([X, X * X, X[:, _CORR_PI] * X[:, _CORR_PJ]], axis=1)
    X = (X - corr["fmu"][li]) * corr["fisd"][li]
    h = fnp.tanh(X @ corr["W1"][li] + corr["b1"][li])
    h = fnp.tanh(h @ corr["W2"][li] + corr["b2"][li])
    return (h @ corr["W3"][li] + corr["b3"][li])[:, 0]



